import ctypes, json, sys, random
from pathlib import Path
DEPS = Path('/workspace/vendor')
ctypes.CDLL(str(DEPS / 'system-libs/libz.so.1'), mode=ctypes.RTLD_GLOBAL)
sys.path.insert(0, str(DEPS))
sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace')
import dev.gen as gen
import dev.reference as ref
from netnomos.finite import compile_job

n = int(sys.argv[1]) if len(sys.argv) > 1 else 200
seed0 = int(sys.argv[2]) if len(sys.argv) > 2 else 0
bad = 0
for it in range(n):
    rng = random.Random(seed0 + it)
    job = gen.make_job(rng)
    try:
        got = compile_job(job)
    except Exception as e:
        print('ENGINE ERROR', it, repr(e)); print(json.dumps(job)); bad += 1; continue
    try:
        exp = ref.compile_job(job)
    except Exception as e:
        print('REF ERROR', it, repr(e)); print(json.dumps(job)); bad += 1; continue
    if got != exp:
        bad += 1
        print('MISMATCH iter', it)
        print('JOB', json.dumps(job))
        for k in ('rules', 'active', 'answers'):
            if got[k] != exp[k]:
                print('key', k)
                print('GOT', json.dumps(got[k])[:2000])
                print('EXP', json.dumps(exp[k])[:2000])
        if bad >= 3:
            break
print('done', n, 'bad', bad)
